&#x2F;&#x2F;Level 47: Din Don Dan
&#x2F;&#x2F;F12 &gt; Console &gt; Paste Code<p>const hitNotesSet = new WeakSet();
const tolerance = 10; &#x2F;&#x2F; hassasiyet<p>const arrowMap = {
  &#x27;←&#x27;: document.querySelector(&#x27;.arrows-container .arrow-key:nth-child(1)&#x27;),
  &#x27;↓&#x27;: document.querySelector(&#x27;.arrows-container .arrow-key:nth-child(2)&#x27;),
  &#x27;↑&#x27;: document.querySelector(&#x27;.arrows-container .arrow-key:nth-child(3)&#x27;),
  &#x27;→&#x27;: document.querySelector(&#x27;.arrows-container .arrow-key:nth-child(4)&#x27;)
};<p>const keyMap = {
  &#x27;↑&#x27;: &#x27;ArrowUp&#x27;,
  &#x27;↓&#x27;: &#x27;ArrowDown&#x27;,
  &#x27;←&#x27;: &#x27;ArrowLeft&#x27;,
  &#x27;→&#x27;: &#x27;ArrowRight&#x27;
};<p>function hitNotes() {
  document.querySelectorAll(&#x27;.note&#x27;).forEach(note =&gt; {
    if (hitNotesSet.has(note)) return;<p><pre><code>    const arrow = note.innerText.trim();
    const target = arrowMap[arrow];
    if (!target) return;

    const noteRect = note.getBoundingClientRect();
    const targetRect = target.getBoundingClientRect();

    const noteY = noteRect.top + noteRect.height &#x2F; 2;
    const targetY = targetRect.top + targetRect.height &#x2F; 2;

    if (Math.abs(noteY - targetY) &lt;= tolerance) {
      const key = keyMap[arrow];
      if (key) {
        console.log(`Basıldı: ${arrow} (${key})`);
        document.dispatchEvent(new KeyboardEvent(&#x27;keydown&#x27;, { key }));
        document.dispatchEvent(new KeyboardEvent(&#x27;keyup&#x27;, { key }));
        hitNotesSet.add(note);
      }
    }
  });</code></pre>
}<p>setInterval(hitNotes, 10);
